param(
    [object]    $Item,
    [hashtable] $Plan,
    [System.Collections.Concurrent.ConcurrentBag[string]] $ErrorBag,
    [int]       $Index
)

$current = $Item

foreach ($step in $Plan.Steps)
{
    if ($current -is [System.Management.Automation.PSObject] -and
        $current.PSObject.Properties['_ChainHalt']) { break }

    try
    {
        $current = & $step.Fn $current $step.Config
    }
    catch
    {
        $ErrorBag.Add("Item [$Index] step '$($step.Key)': $($_.Exception.Message)")
        break
    }
}

return $current

param($Item, $Config)

$result = [PSCustomObject]@{
    AbsolutePath = $Item.AbsolutePath
    SizeBytes    = $Item.SizeBytes
    RelativePath = $Item.RelativePath
    NodePath     = $Item.NodePath
}

try
{
    $bytes = [System.IO.File]::ReadAllBytes($result.AbsolutePath)

    if ($bytes -contains 0)
    {
        $result | Add-Member -NotePropertyName ReadError -NotePropertyValue 'BinaryOrNulContent'
        $result | Add-Member -NotePropertyName _ChainHalt -NotePropertyValue $true
        return $result
    }

    $enc = [System.Text.Encoding]::UTF8
    $content = $enc.GetString($bytes)

    $result | Add-Member -NotePropertyName Content -NotePropertyValue $content
    $result | Add-Member -NotePropertyName Encoding -NotePropertyValue 'UTF-8'
    return $result
}
catch
{
    $result | Add-Member -NotePropertyName ReadError -NotePropertyValue $_.Exception.Message
    $result | Add-Member -NotePropertyName _ChainHalt -NotePropertyValue $true
    return $result
}

param(
    [Parameter(Position = 0)]
    [object]$Item,
    [Parameter(Position = 1)]
    [hashtable]$Config = @{}
)

$ops = if ($Config.ContainsKey('Operations')) { @($Config['Operations']) } else { @('lf', 'no-bom', 'nfc', 'strip-zwsp', 'trim-trailing', 'trim-inner', 'max-blank-2', 'trim-doc') }

$text = $null
$path = $null
$id = $null

if ($Item -is [string])
{
    $text = $Item
}
elseif ($Item -is [hashtable] -or $Item -is [pscustomobject])
{
    if ($null -ne $Item.PSObject.Properties['Text']) { $text = [string]$Item.Text }
    if ($null -ne $Item.PSObject.Properties['Path']) { $path = [string]$Item.Path }
    if ($null -ne $Item.PSObject.Properties['Id']) { $id = [string]$Item.Id }
}

if ([string]::IsNullOrEmpty($text))
{
    $text = ''
}

$t = $text

if ('lf' -in $ops)
{
    $t = $t -replace "`r`n", "`n" -replace "`r", "`n"
}

if ('no-bom' -in $ops)
{
    $t = $t -replace '^\uFEFF', ''
}

if ('nfc' -in $ops)
{
    try { $t = $t.Normalize([System.Text.NormalizationForm]::FormC) } catch {}
}

if ('strip-zwsp' -in $ops)
{
    $t = $t -replace '[\u200B\u200C\u200D\u2060\uFEFF]', ''
}

if ('trim-trailing' -in $ops)
{
    $t = ($t -split "`n" | ForEach-Object { $_.TrimEnd() }) -join "`n"
}

if ('trim-inner' -in $ops)
{
    $t = $t -replace '(?<=\S) {2,}(?=\S)', ' '
}

if ('max-blank-2' -in $ops)
{
    $t = $t -replace "(`n){4,}", "`n`n`n"
}

if ('max-blank-1' -in $ops)
{
    $t = $t -replace "(`n){3,}", "`n`n"
}

if ('trim-doc' -in $ops)
{
    $t = $t -replace '^\n+', '' -replace '\n+$', ''
}

if ('eof-eot' -in $ops)
{
    $t = $t.TrimEnd("`r", "`n") + "`n`u{0004}"
}

$includeMeta = $true
if ($null -ne $Config['IncludeMeta']) { $includeMeta = [bool]$Config['IncludeMeta'] }

if (-not $includeMeta)
{
    return $t
}

return [pscustomobject]@{
    Id         = $id
    Path       = $path
    Text       = $t
    Operations = @($ops)
    Processor  = 'format'
}

param(
    [Parameter(Position = 0)]
    [object]$Item,

    [Parameter(Position = 1)]
    [hashtable]$Config = @{}
)

$ops = if ($Config.ContainsKey('Operations')) { @($Config['Operations']) } else { @('block-comments', 'doc-strings', 'comment-blocks', 'line-comments') }
$includeMeta = if ($null -ne $Config['IncludeMeta']) { [bool]$Config['IncludeMeta'] } else { $true }

$text = $null
$path = $null
$id = $null

if ($Item -is [string])
{
    $text = $Item
}
elseif ($Item -is [hashtable] -or $Item -is [pscustomobject])
{
    if ($null -ne $Item.PSObject.Properties['Text']) { $text = [string]$Item.Text }
    if ($null -ne $Item.PSObject.Properties['Path']) { $path = [string]$Item.Path }
    if ($null -ne $Item.PSObject.Properties['Id']) { $id = [string]$Item.Id }
}

if ([string]::IsNullOrEmpty($text))
{
    if (-not $includeMeta) { return '' }
    return [pscustomobject]@{
        Id         = $id
        Path       = $path
        Text       = ''
        Operations = @($ops)
        Processor  = 'rs-csstrip'
    }
}

$text = $text -replace "`r`n", "`n" -replace "`r", "`n"

$spansToStrip = [System.Collections.Generic.List[pscustomobject]]::new()

$stripBlock    = 'block-comments'    -in $ops
$stripInterior = 'interior-comments' -in $ops
$stripDoc         = 'doc-strings'           -in $ops
$stripCB          = 'comment-blocks'        -in $ops
$stripLine        = 'line-comments'         -in $ops
$stripInline      = 'inline-comments'       -in $ops

if ($stripBlock -or $stripInterior)
{
    $rx = [regex]::new('(?s)/\*.*?\*/', 'None')
    foreach ($m in $rx.Matches($text))
    {
        $s = $m.Index
        $e = $m.Index + $m.Length

        $ls = $s
        while ($ls -gt 0 -and ($text[$ls - 1] -eq ' ' -or $text[$ls - 1] -eq "`t")) { $ls-- }
        $standaloneStart = ($ls -eq 0 -or $text[$ls - 1] -eq "`n")

        $lineEnd = $text.IndexOf("`n", $e)
        if ($lineEnd -eq -1) { $lineEnd = $text.Length }
        $standaloneEnd = ($text.Substring($e, $lineEnd - $e) -notmatch '\S')

        if ($standaloneStart -and $standaloneEnd)
        {
            if (-not $stripBlock) { continue }

            $s = $ls
            if ($e -lt $text.Length -and $text[$e] -eq "`n") { $e++ }
        }
        else
        {
            if (-not $stripInterior) { continue }

        }

        $spansToStrip.Add([pscustomobject]@{ Start = $s; End = $e })
    }
}

if ($stripDoc)
{
    $rxDoc = [regex]::new('(?m)^([^\S\n]*)///[^\n]*(\n)?', 'None')
    foreach ($m in $rxDoc.Matches($text))
    {
        $spansToStrip.Add([pscustomobject]@{ Start = $m.Index; End = $m.Index + $m.Length })
    }
}

if ($stripCB -or $stripLine)
{
    $rxLine = [regex]::new('(?m)^([^\S\n]*)//(?!/)[^\n]*(\n)?', 'None')

    $standaloneMatches = [System.Collections.Generic.List[pscustomobject]]::new()

    foreach ($m in $rxLine.Matches($text))
    {

        $slashIdx = $m.Index + $m.Groups[1].Length
        $before = $text.Substring($m.Index, $slashIdx - $m.Index)
        if ($before -match '\S') { continue }   # code before // → InlineComment, handled below

        $lineNum = ($text.Substring(0, $m.Index) -split "`n").Count

        $standaloneMatches.Add([pscustomobject]@{
                LineNum = $lineNum
                Start   = $m.Index
                End     = $m.Index + $m.Length
            })
    }

    $runStartI = -1
    $runEndI = -1
    $cbFlags = @($false) * $standaloneMatches.Count

    for ($i = 0; $i -lt $standaloneMatches.Count; $i++)
    {
        $cur = $standaloneMatches[$i]
        if ($runStartI -eq -1)
        {
            $runStartI = $i; $runEndI = $i
        }
        elseif ($cur.LineNum -eq $standaloneMatches[$runEndI].LineNum + 1)
        {
            $runEndI = $i
        }
        else
        {
            if ($runEndI -gt $runStartI) { for ($j = $runStartI; $j -le $runEndI; $j++) { $cbFlags[$j] = $true } }
            $runStartI = $i; $runEndI = $i
        }
    }
    if ($runStartI -ne -1 -and $runEndI -gt $runStartI) { for ($j = $runStartI; $j -le $runEndI; $j++) { $cbFlags[$j] = $true } }

    for ($i = 0; $i -lt $standaloneMatches.Count; $i++)
    {
        $shouldStrip = if ($cbFlags[$i]) { $stripCB } else { $stripLine }
        if (-not $shouldStrip) { continue }
        $sm = $standaloneMatches[$i]
        $ls2 = $sm.Start
        while ($ls2 -gt 0 -and ($text[$ls2 - 1] -eq ' ' -or $text[$ls2 - 1] -eq "`t")) { $ls2-- }
        $s2 = if ($ls2 -eq 0 -or $text[$ls2 - 1] -eq "`n") { $ls2 } else { $sm.Start }
        $spansToStrip.Add([pscustomobject]@{ Start = $s2; End = $sm.End })
    }
}

if ($stripInline)
{
    $rxInline = [regex]::new('[ \t]*//(?!/)[^\n]*', 'None')
    foreach ($m in $rxInline.Matches($text))
    {
        $lineStart = $text.LastIndexOf("`n", $m.Index)
        $lineStart = if ($lineStart -eq -1) { 0 } else { $lineStart + 1 }
        $before = $text.Substring($lineStart, $m.Index - $lineStart)
        if ($before -notmatch '\S') { continue }
        $spansToStrip.Add([pscustomobject]@{ Start = $m.Index; End = $m.Index + $m.Length })
    }
}

$merged = [System.Collections.Generic.List[pscustomobject]]::new()

if ($spansToStrip.Count -gt 0)
{
    $sorted = @($spansToStrip | Sort-Object { $_.Start })
    $cur = [pscustomobject]@{ Start = $sorted[0].Start; End = $sorted[0].End }

    for ($i = 1; $i -lt $sorted.Count; $i++)
    {
        $nxt = $sorted[$i]
        if ($nxt.Start -le $cur.End)
        {
            if ($nxt.End -gt $cur.End) { $cur = [pscustomobject]@{ Start = $cur.Start; End = $nxt.End } }
        }
        else
        {
            $merged.Add($cur)
            $cur = [pscustomobject]@{ Start = $nxt.Start; End = $nxt.End }
        }
    }
    $merged.Add($cur)
}

$sb = [System.Text.StringBuilder]::new($text.Length)
$pos = 0

foreach ($span in $merged)
{
    if ($span.Start -gt $pos)
    {
        $null = $sb.Append($text.Substring($pos, $span.Start - $pos))
    }
    $pos = $span.End
}
if ($pos -lt $text.Length)
{
    $null = $sb.Append($text.Substring($pos))
}

$result = $sb.ToString()

if (-not $includeMeta) { return $result }

return [pscustomobject]@{
    Id         = $id
    Path       = $path
    Text       = $result
    Operations = @($ops)
    Processor  = 'rs-csstrip'
}

param(
    [Parameter(Position = 0)]
    [object]$Item,

    [Parameter(Position = 1)]
    [hashtable]$Config = @{}
)

$ops = @($Config['Operations'])

$includeMeta = if ($null -ne $Config['IncludeMeta']) { [bool]$Config['IncludeMeta'] } else { $true }
$targetUnit = if ($null -ne $Config['TargetUnit'] -and [int]$Config['TargetUnit'] -gt 0) { [int]$Config['TargetUnit'] } else { 2 }

$text = $null
$path = $null
$id = $null

if ($Item -is [string])
{
    $text = $Item
}
elseif ($Item -is [hashtable])
{
    if ($Item.ContainsKey('Text')) { $text = [string]$Item['Text'] }
    if ($Item.ContainsKey('Path')) { $path = [string]$Item['Path'] }
    if ($Item.ContainsKey('Id')) { $id = [string]$Item['Id'] }
}
elseif ($Item -is [pscustomobject])
{
    if ($null -ne $Item.PSObject.Properties['Text']) { $text = [string]$Item.Text }
    if ($null -ne $Item.PSObject.Properties['Path']) { $path = [string]$Item.Path }
    if ($null -ne $Item.PSObject.Properties['Id']) { $id = [string]$Item.Id }
}

if ([string]::IsNullOrEmpty($text)) { $text = '' }

$ext = if ($path) { [IO.Path]::GetExtension($path).ToLowerInvariant() } else { '' }
$skipExts = @('.md', '.txt', '.rst', '.html', '.htm', '.xml', '.json', '.yaml', '.yml', '.toml', '.csv')

if ($ext -in $skipExts)
{
    if (-not $includeMeta) { return $text }
    return [pscustomobject]@{
        Id         = $id
        Path       = $path
        Text       = $text
        Operations = @($ops)
        Skipped    = $true
        Processor  = 'rs-indent'
    }
}

if ($text -eq '')
{
    if (-not $includeMeta) { return '' }
    return [pscustomobject]@{
        Id         = $id
        Path       = $path
        Text       = ''
        Operations = @($ops)
        Processor  = 'rs-indent'
    }
}

$doStripCommon = 'strip-common' -in $ops
$doDetab = 'detab' -in $ops -or 'min-indent-2' -in $ops -or 'tabify' -in $ops
$doMinIndent = 'min-indent-2' -in $ops
$doTabify = 'tabify' -in $ops

$lines = $text -split "`n"
$depths = [int[]]::new($lines.Count)

if ($doStripCommon)
{
    $spaceLeads = [System.Collections.Generic.List[int]]::new()
    foreach ($line in $lines)
    {
        if ($line -match '\S')
        {
            $m = [regex]::Match($line, '^ +')
            $depth = if ($m.Success) { $m.Length } else { 0 }
            $spaceLeads.Add($depth)
        }
    }

    if ($spaceLeads.Count -gt 0)
    {
        $common = ($spaceLeads | Measure-Object -Minimum).Minimum
        if ($common -gt 0)
        {
            for ($i = 0; $i -lt $lines.Count; $i++)
            {
                if ($lines[$i] -match '\S')
                {
                    $m = [regex]::Match($lines[$i], '^ +')
                    $leadSpaces = if ($m.Success) { $m.Length } else { 0 }
                    $strip = [math]::Min($common, $leadSpaces)
                    if ($strip -gt 0) { $lines[$i] = $lines[$i].Substring($strip) }
                }
            }
        }
    }
}

if ($doDetab)
{
    for ($i = 0; $i -lt $lines.Count; $i++)
    {
        $seg = [regex]::Match($lines[$i], '^\s+').Value
        if (-not $seg) { $depths[$i] = 0; continue }

        if ($seg -match '\t')
        {
            $expanded = $seg -replace '\t', (' ' * $targetUnit)
            $lines[$i] = $expanded + $lines[$i].Substring($seg.Length)
            $seg = $expanded
        }

        $depths[$i] = $seg.Length
    }
}

if ($doMinIndent)
{
    $nonZero = @($depths | Where-Object { $_ -gt 0 })
    if ($nonZero.Count -gt 0)
    {
        $gcd = $nonZero[0]
        for ($i = 1; $i -lt $nonZero.Count; $i++)
        {
            $a = $gcd; $b = $nonZero[$i]
            while ($b -ne 0) { $tmp = $a % $b; $a = $b; $b = $tmp }
            $gcd = $a
        }

        if ($gcd -gt 0 -and $gcd -ne $targetUnit)
        {
            for ($i = 0; $i -lt $lines.Count; $i++)
            {
                if ($depths[$i] -gt 0)
                {
                    $newDepth = [int]($depths[$i] * $targetUnit / $gcd)
                    $rest = $lines[$i].Substring($depths[$i])
                    $lines[$i] = (' ' * $newDepth) + $rest
                    $depths[$i] = $newDepth
                }
            }
        }
    }
}

if ($doTabify)
{
    for ($i = 0; $i -lt $lines.Count; $i++)
    {
        if ($depths[$i] -gt 0)
        {
            $tabs = [math]::Floor($depths[$i] / $targetUnit)
            $remainder = $depths[$i] % $targetUnit
            $rest = $lines[$i].Substring($depths[$i])
            $lines[$i] = ("`t" * $tabs) + (' ' * $remainder) + $rest
        }
    }
}

$t = $lines -join "`n"

if (-not $includeMeta) { return $t }

return [pscustomobject]@{
    Id         = $id
    Path       = $path
    Text       = $t
    Operations = @($ops)
    Processor  = 'rs-indent'
}

param(
    [Parameter(Position = 0)]
    [object]$Item,

    [Parameter(Position = 1)]
    [hashtable]$Config = @{}
)

$ops = if ($Config.ContainsKey('Operations')) { @($Config['Operations']) } else { @('block-comments', 'doc-strings', 'comment-blocks', 'line-comments') }
$includeMeta = if ($null -ne $Config['IncludeMeta']) { [bool]$Config['IncludeMeta'] } else { $true }

$text = $null
$path = $null
$id = $null

if ($Item -is [string])
{
    $text = $Item
}
elseif ($Item -is [hashtable] -or $Item -is [pscustomobject])
{
    if ($null -ne $Item.PSObject.Properties['Text']) { $text = [string]$Item.Text }
    if ($null -ne $Item.PSObject.Properties['Path']) { $path = [string]$Item.Path }
    if ($null -ne $Item.PSObject.Properties['Id']) { $id = [string]$Item.Id }
}

if ([string]::IsNullOrEmpty($text))
{
    if (-not $includeMeta) { return '' }
    return [pscustomobject]@{
        Id         = $id
        Path       = $path
        Text       = ''
        Operations = @($ops)
        Processor  = 'rs-psstrip'
    }
}

$tokensRef = [ref]$null
$errorsRef = [ref]$null
$ast = [System.Management.Automation.Language.Parser]::ParseInput($text, $tokensRef, $errorsRef)
$tokens = @($tokensRef.Value)
$errors = @($errorsRef.Value)

$parseErrors = $null
if ($errors.Count -gt 0)
{
    $parseErrors = @($errors | ForEach-Object { $_.Message })
}

if ($null -ne $parseErrors)
{

    $spansToStrip = [System.Collections.Generic.List[pscustomobject]]::new()
    $stripBlock = ('block-comments' -in $ops) -or ('doc-strings' -in $ops)
    $stripCB = 'comment-blocks' -in $ops
    $stripLine = 'line-comments' -in $ops
    $stripInline = 'inline-comments' -in $ops

    if ($stripBlock)
    {
        $rx = [regex]::new('(?s)', 'None')
        foreach ($m in $rx.Matches($text))
        {
            $s = $m.Index
            $e = $m.Index + $m.Length

            $ls = $s
            while ($ls -gt 0 -and ($text[$ls - 1] -eq ' ' -or $text[$ls - 1] -eq "`t")) { $ls-- }
            if ($ls -eq 0 -or $text[$ls - 1] -eq "`n" -or $text[$ls - 1] -eq "`r") { $s = $ls }
            if ($e -lt $text.Length)
            {
                if ($text[$e] -eq "`r") { $e++; if ($e -lt $text.Length -and $text[$e] -eq "`n") { $e++ } }
                elseif ($text[$e] -eq "`n") { $e++ }
            }
            $spansToStrip.Add([pscustomobject]@{ Start = $s; End = $e })
        }
    }

    if ($stripCB -or $stripLine)
    {

        $rxLine = [regex]::new('(?m)^([^\S\r\n]*)#(?!requires\b)[^\r\n]*(\r?\n)?', 'None')

        $standaloneMatches = [System.Collections.Generic.List[pscustomobject]]::new()
        $textLines = $text -split "`n"
        foreach ($m in $rxLine.Matches($text))
        {

            $lineStart = $m.Index
            $hashIdx = $m.Index + $m.Groups[1].Length   # position of the # character
            $before = $text.Substring($lineStart, $hashIdx - $lineStart)
            if ($before -match '\S') { continue }   # has code before # → InlineComment, handled below

            $lineNum = ($text.Substring(0, $m.Index) -split "`n").Count

            $standaloneMatches.Add([pscustomobject]@{
                    LineNum = $lineNum
                    Start   = $m.Index
                    End     = $m.Index + $m.Length
                })
        }

        $runStartI = -1
        $runEndI = -1
        $cbFlags = @($false) * $standaloneMatches.Count

        for ($i = 0; $i -lt $standaloneMatches.Count; $i++)
        {
            $cur2 = $standaloneMatches[$i]
            if ($runStartI -eq -1)
            {
                $runStartI = $i; $runEndI = $i
            }
            elseif ($cur2.LineNum -eq $standaloneMatches[$runEndI].LineNum + 1)
            {
                $runEndI = $i
            }
            else
            {
                if ($runEndI -gt $runStartI) { for ($j = $runStartI; $j -le $runEndI; $j++) { $cbFlags[$j] = $true } }
                $runStartI = $i; $runEndI = $i
            }
        }
        if ($runStartI -ne -1 -and $runEndI -gt $runStartI) { for ($j = $runStartI; $j -le $runEndI; $j++) { $cbFlags[$j] = $true } }

        for ($i = 0; $i -lt $standaloneMatches.Count; $i++)
        {
            $shouldStrip2 = if ($cbFlags[$i]) { $stripCB } else { $stripLine }
            if (-not $shouldStrip2) { continue }
            $sm = $standaloneMatches[$i]
            $ls2 = $sm.Start
            while ($ls2 -gt 0 -and ($text[$ls2 - 1] -eq ' ' -or $text[$ls2 - 1] -eq "`t")) { $ls2-- }
            $s2 = if ($ls2 -eq 0 -or $text[$ls2 - 1] -eq "`n" -or $text[$ls2 - 1] -eq "`r") { $ls2 } else { $sm.Start }
            $spansToStrip.Add([pscustomobject]@{ Start = $s2; End = $sm.End })
        }
    }

    if ($stripInline)
    {
        $rxInline = [regex]::new('(?m)[ \t]*#(?!requires\b)[^\r\n]*', 'None')
        foreach ($m in $rxInline.Matches($text))
        {

            $lineStart = $text.LastIndexOf("`n", $m.Index)
            $lineStart = if ($lineStart -eq -1) { 0 } else { $lineStart + 1 }
            $before2 = $text.Substring($lineStart, $m.Index - $lineStart)
            if ($before2 -notmatch '\S') { continue }
            $spansToStrip.Add([pscustomobject]@{ Start = $m.Index; End = $m.Index + $m.Length })
        }
    }
}
else
{

    $bodyExtents = [System.Collections.Generic.List[System.Management.Automation.Language.IScriptExtent]]::new()

    $ast.FindAll(
        {
            param($node)
            $node -is [System.Management.Automation.Language.FunctionDefinitionAst] -or
            $node -is [System.Management.Automation.Language.TypeDefinitionAst]
        },
        $true
    ) | ForEach-Object { $bodyExtents.Add($_.Extent) }

    $commentKind = [System.Management.Automation.Language.TokenKind]::Comment

    $lines = $text -split "`n"

    $commentTokens = @(
        $tokens |
        Where-Object { $_.Kind -eq $commentKind } |
        Sort-Object { $_.Extent.StartOffset }
    )

    $classified = [System.Collections.Generic.List[pscustomobject]]::new()

    foreach ($tok in $commentTokens)
    {
        $so = $tok.Extent.StartOffset
        $eo = $tok.Extent.EndOffset
        $line = $tok.Extent.StartLineNumber    # 1-indexed
        $col = $tok.Extent.StartColumnNumber  # 1-indexed

        if ($tok.Text -match '^<#')
        {

            $isInBody = $false
            foreach ($ext in $bodyExtents)
            {
                if ($so -ge $ext.StartOffset -and $eo -le $ext.EndOffset) { $isInBody = $true; break }
            }
            $kind = if ($isInBody) { 'DocString' } else { 'BlockComment' }
        }
        else
        {

            $kind = 'LineComment'
            $lineIdx = $line - 1
            if ($lineIdx -ge 0 -and $lineIdx -lt $lines.Count)
            {
                $lineText = $lines[$lineIdx]
                $beforeLen = [Math]::Min($col - 1, $lineText.Length)
                if ($beforeLen -gt 0 -and $lineText.Substring(0, $beforeLen) -match '\S')
                {
                    $kind = 'InlineComment'
                }
            }
        }

        $classified.Add([pscustomobject]@{
                Token    = $tok
                Kind     = $kind
                StartOff = $so
                EndOff   = $eo
                LineNum  = $line
            })
    }

    $runStartI = -1
    $runEndI = -1

    for ($i = 0; $i -lt $classified.Count; $i++)
    {
        $c = $classified[$i]
        if ($c.Kind -ne 'LineComment') { continue }

        if ($runStartI -eq -1)
        {
            $runStartI = $i
            $runEndI = $i
        }
        elseif ($c.LineNum -eq $classified[$runEndI].LineNum + 1)
        {
            $runEndI = $i
        }
        else
        {
            if ($runEndI -gt $runStartI)
            {
                for ($j = $runStartI; $j -le $runEndI; $j++) { $classified[$j].Kind = 'CommentBlock' }
            }
            $runStartI = $i
            $runEndI = $i
        }
    }

    if ($runStartI -ne -1 -and $runEndI -gt $runStartI)
    {
        for ($j = $runStartI; $j -le $runEndI; $j++) { $classified[$j].Kind = 'CommentBlock' }
    }

    $spansToStrip = [System.Collections.Generic.List[pscustomobject]]::new()

    foreach ($c in $classified)
    {
        $shouldStrip = switch ($c.Kind)
        {
            'BlockComment' { 'block-comments' -in $ops }
            'DocString' { 'doc-strings' -in $ops }
            'CommentBlock' { 'comment-blocks' -in $ops }
            'LineComment' { 'line-comments' -in $ops }
            'InlineComment' { 'inline-comments' -in $ops }
            default { $false }
        }
        if (-not $shouldStrip) { continue }

        $spanStart = $c.StartOff
        $spanEnd = $c.EndOff

        if ($c.Kind -eq 'InlineComment')
        {

            $ws = $spanStart
            while ($ws -gt 0 -and ($text[$ws - 1] -eq ' ' -or $text[$ws - 1] -eq "`t")) { $ws-- }
            $spanStart = $ws
        }
        else
        {

            $ls = $spanStart
            while ($ls -gt 0 -and ($text[$ls - 1] -eq ' ' -or $text[$ls - 1] -eq "`t")) { $ls-- }
            if ($ls -eq 0 -or $text[$ls - 1] -eq "`n" -or $text[$ls - 1] -eq "`r")
            {
                $spanStart = $ls
            }

            if ($spanEnd -lt $text.Length)
            {
                if ($text[$spanEnd] -eq "`r")
                {
                    $spanEnd++
                    if ($spanEnd -lt $text.Length -and $text[$spanEnd] -eq "`n") { $spanEnd++ }
                }
                elseif ($text[$spanEnd] -eq "`n")
                {
                    $spanEnd++
                }
            }
        }

        $spansToStrip.Add([pscustomobject]@{ Start = $spanStart; End = $spanEnd })
    }

} # end else (AST path)

$merged = [System.Collections.Generic.List[pscustomobject]]::new()

if ($spansToStrip.Count -gt 0)
{
    $sorted = @($spansToStrip | Sort-Object { $_.Start })
    $cur = [pscustomobject]@{ Start = $sorted[0].Start; End = $sorted[0].End }

    for ($i = 1; $i -lt $sorted.Count; $i++)
    {
        $nxt = $sorted[$i]
        if ($nxt.Start -le $cur.End)
        {
            if ($nxt.End -gt $cur.End) { $cur = [pscustomobject]@{ Start = $cur.Start; End = $nxt.End } }
        }
        else
        {
            $merged.Add($cur)
            $cur = [pscustomobject]@{ Start = $nxt.Start; End = $nxt.End }
        }
    }
    $merged.Add($cur)
}

$sb = [System.Text.StringBuilder]::new($text.Length)
$pos = 0

foreach ($span in $merged)
{
    if ($span.Start -gt $pos)
    {
        $null = $sb.Append($text.Substring($pos, $span.Start - $pos))
    }
    $pos = $span.End
}
if ($pos -lt $text.Length)
{
    $null = $sb.Append($text.Substring($pos))
}

$result = $sb.ToString()

if (-not $includeMeta) { return $result }

$envelope = [ordered]@{
    Id         = $id
    Path       = $path
    Text       = $result
    Operations = @($ops)
    Processor  = 'rs-psstrip'
}
if ($null -ne $parseErrors)
{
    $envelope['ParseErrors'] = $parseErrors
    $envelope['FallbackMode'] = 'regex'
}
return [pscustomobject]$envelope

param(
    [Parameter(Position = 0)]
    [object]$Item,

    [Parameter(Position = 1)]
    [hashtable]$Config = @{}
)

$includeMeta = if ($null -ne $Config['IncludeMeta']) { [bool]$Config['IncludeMeta'] } else { $true }

$stripInlineCites = if ($null -ne $Config['StripInlineCites']) { [bool]$Config['StripInlineCites'] } else { $false }

$text = $null
$path = $null
$id = $null

if ($Item -is [string])
{
    $text = $Item
}
elseif ($Item -is [hashtable] -or $Item -is [pscustomobject])
{
    if ($null -ne $Item.PSObject.Properties['Text']) { $text = [string]$Item.Text }
    elseif ($null -ne $Item.PSObject.Properties['Content']) { $text = [string]$Item.Content }
    if ($null -ne $Item.PSObject.Properties['Path']) { $path = [string]$Item.Path }
    if ($null -ne $Item.PSObject.Properties['Id']) { $id = [string]$Item.Id }
}

if ([string]::IsNullOrEmpty($text))
{
    if (-not $includeMeta) { return @() }
    return [pscustomobject]@{
        Id        = $id
        Path      = $path
        Exchanges = @()
        Processor = 'threadparser-perplexity'
    }
}

$text = $text -replace "`r`n", "`n" -replace "`r", "`n"

$text = $text.TrimEnd()
while ($text -match '\n[ \t]*-{3,}[ \t]*$')
{
    $text = ($text -replace '\n[ \t]*-{3,}[ \t]*$', '').TrimEnd()
}

$SENT_OPEN = [char]0xE000
$SENT_CLOSE = [char]0xE001
$RX_NB = [System.Text.RegularExpressions.RegexOptions]::NonBacktracking
$RX_NB_M = $RX_NB -bor [System.Text.RegularExpressions.RegexOptions]::Multiline

function _MaskByRegex
{
    param(
        [string]$InputText,
        [System.Text.RegularExpressions.Regex]$Rx,
        [string]$Tag,
        [System.Collections.Generic.List[object]]$Store
    )

    $matches = $Rx.Matches($InputText)
    if ($matches.Count -eq 0) { return $InputText }

    $sb = [System.Text.StringBuilder]::new($InputText.Length)
    $pos = 0
    foreach ($m in $matches)
    {
        if ($m.Index -gt $pos) { [void]$sb.Append($InputText.Substring($pos, $m.Index - $pos)) }
        $i = $Store.Count
        $Store.Add($m.Value)
        [void]$sb.Append("$SENT_OPEN$Tag`:$i$SENT_CLOSE")
        $pos = $m.Index + $m.Length
    }
    if ($pos -lt $InputText.Length) { [void]$sb.Append($InputText.Substring($pos)) }
    return $sb.ToString()
}

$text = [regex]::Replace(
    $text,
    '(?is)<span\s+style\s*=\s*"display:\s*none[^"]*"[^>]*>.*?</span>',
    ''
)
$text = [regex]::Replace(
    $text,
    '(?is)<div\s+align\s*=\s*"center"[^>]*>.*?</div>',
    ''
)

$codeBlocks = [System.Collections.Generic.List[object]]::new()
$rxCode = [regex]::new(
    '(?ms)^[ \t]*`{3,}[^\n]*\n.*?\n[ \t]*`{3,}[ \t]*$',
    $RX_NB_M
)
$text = _MaskByRegex -InputText $text -Rx $rxCode -Tag 'CODE' -Store $codeBlocks

$footerBlocks = [System.Collections.Generic.List[object]]::new()
$rxFooter = [regex]::new(
    '(?m)(?:^\[\^[\w]+\]:[^\n]*\n?)+',
    $RX_NB_M
)
$rxFooterEntry = [regex]::new('(?m)^\[\^([\w]+)\]:\s*(.+?)\s*$')

$footerMatches = $rxFooter.Matches($text)
if ($footerMatches.Count -gt 0)
{
    $sb = [System.Text.StringBuilder]::new($text.Length)
    $pos = 0
    foreach ($m in $footerMatches)
    {
        if ($m.Index -gt $pos) { [void]$sb.Append($text.Substring($pos, $m.Index - $pos)) }

        $entries = [System.Collections.Generic.List[object]]::new()
        foreach ($em in $rxFooterEntry.Matches($m.Value))
        {
            $entries.Add([pscustomobject]@{
                    Id      = $em.Groups[1].Value
                    Content = $em.Groups[2].Value
                })
        }
        $i = $footerBlocks.Count
        $footerBlocks.Add($entries.ToArray())
        [void]$sb.Append("$SENT_OPEN`FOOTER:$i$SENT_CLOSE")
        $pos = $m.Index + $m.Length
    }
    if ($pos -lt $text.Length) { [void]$sb.Append($text.Substring($pos)) }
    $text = $sb.ToString()
}

$inlineCites = [System.Collections.Generic.List[object]]::new()
$rxInlineCite = [regex]::new(
    '\[\^[\w]+\](?:\s*(?:and\s+)?\[\^[\w]+\])*',
    [System.Text.RegularExpressions.RegexOptions]::None
)
$text = _MaskByRegex -InputText $text -Rx $rxInlineCite -Tag 'CITE' -Store $inlineCites

$rxFooterSent = [regex]::new("$SENT_OPEN`FOOTER:\d+$SENT_CLOSE")
$rxHr = [regex]::new('(?m)^[ \t]*-{3,}[ \t]*$')
$rxNextH1 = [regex]::new('\A[\r\n \t]*#[ \t]+\S')

$splitSpans = [System.Collections.Generic.List[object]]::new()
foreach ($m in $rxHr.Matches($text))
{
    $isTerminus = $false

    $back = $m.Index - 1
    while ($back -ge 0)
    {
        $ch = $text[$back]
        if ($ch -ne ' ' -and $ch -ne "`t" -and $ch -ne "`n" -and $ch -ne "`r") { break }
        $back--
    }
    if ($back -ge 0)
    {
        $scanStart = [math]::Max(0, $back - 32)
        $window = $text.Substring($scanStart, $back - $scanStart + 1)
        if ($rxFooterSent.IsMatch($window)) { $isTerminus = $true }
    }

    if (-not $isTerminus)
    {
        $forwardStart = $m.Index + $m.Length
        if ($forwardStart -lt $text.Length)
        {
            $forward = $text.Substring($forwardStart, [math]::Min(256, $text.Length - $forwardStart))
            if ($rxNextH1.IsMatch($forward)) { $isTerminus = $true }
        }
    }

    if ($isTerminus)
    {
        $splitSpans.Add([pscustomobject]@{
                Start = $m.Index
                End   = $m.Index + $m.Length
            })
    }
}

$chunks = [System.Collections.Generic.List[string]]::new()
$prev = 0
foreach ($s in $splitSpans)
{
    if ($s.Start -gt $prev)
    {
        $chunks.Add($text.Substring($prev, $s.Start - $prev))
    }
    $prev = $s.End
}
if ($prev -lt $text.Length)
{
    $chunks.Add($text.Substring($prev))
}

$chunks = @($chunks | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })

$rxH1 = [regex]::new('(?m)^[ \t]*#[ \t]+(.*?)[ \t]*$')
$rxCodeSent = [regex]::new("$SENT_OPEN`CODE:(\d+)$SENT_CLOSE")
$rxCiteSent = [regex]::new("$SENT_OPEN`CITE:(\d+)$SENT_CLOSE")

$exchanges = [System.Collections.Generic.List[object]]::new()
$exchangeIdx = 0

foreach ($chunk in $chunks)
{
    $body = $chunk.Trim()
    if ([string]::IsNullOrEmpty($body)) { continue }

    $citations = @()
    $fm = $rxFooterSent.Match($body)
    if ($fm.Success)
    {
        $idxMatch = [regex]::Match($fm.Value, 'FOOTER:(\d+)')
        if ($idxMatch.Success)
        {
            $bi = [int]$idxMatch.Groups[1].Value
            if ($bi -ge 0 -and $bi -lt $footerBlocks.Count)
            {
                $citations = $footerBlocks[$bi]
            }
        }

        $body = $rxFooterSent.Replace($body, '').TrimEnd()
    }

    $h1Match = $rxH1.Match($body)
    $prompt = ''
    $reply = ''

    if ($h1Match.Success)
    {

        $prompt = $h1Match.Groups[1].Value
        $afterH1 = $body.Substring($h1Match.Index + $h1Match.Length)
        $reply = ($afterH1 -replace '^[\r\n \t]+', '').TrimEnd()
    }
    else
    {

        $reply = $body
    }

    if ($prompt -and $rxCodeSent.IsMatch($prompt))
    {
        $sb = [System.Text.StringBuilder]::new($prompt.Length)
        $pos = 0
        foreach ($m in $rxCodeSent.Matches($prompt))
        {
            if ($m.Index -gt $pos) { [void]$sb.Append($prompt.Substring($pos, $m.Index - $pos)) }
            [void]$sb.Append([string]$codeBlocks[[int]$m.Groups[1].Value])
            $pos = $m.Index + $m.Length
        }
        if ($pos -lt $prompt.Length) { [void]$sb.Append($prompt.Substring($pos)) }
        $prompt = $sb.ToString()
    }
    if ($reply -and $rxCodeSent.IsMatch($reply))
    {
        $sb = [System.Text.StringBuilder]::new($reply.Length)
        $pos = 0
        foreach ($m in $rxCodeSent.Matches($reply))
        {
            if ($m.Index -gt $pos) { [void]$sb.Append($reply.Substring($pos, $m.Index - $pos)) }
            [void]$sb.Append([string]$codeBlocks[[int]$m.Groups[1].Value])
            $pos = $m.Index + $m.Length
        }
        if ($pos -lt $reply.Length) { [void]$sb.Append($reply.Substring($pos)) }
        $reply = $sb.ToString()
    }

    if ($stripInlineCites)
    {
        if ($prompt) { $prompt = $rxCiteSent.Replace($prompt, '') }
        if ($reply) { $reply = $rxCiteSent.Replace($reply, '') }
    }
    else
    {
        if ($prompt -and $rxCiteSent.IsMatch($prompt))
        {
            $sb = [System.Text.StringBuilder]::new($prompt.Length)
            $pos = 0
            foreach ($m in $rxCiteSent.Matches($prompt))
            {
                if ($m.Index -gt $pos) { [void]$sb.Append($prompt.Substring($pos, $m.Index - $pos)) }
                [void]$sb.Append([string]$inlineCites[[int]$m.Groups[1].Value])
                $pos = $m.Index + $m.Length
            }
            if ($pos -lt $prompt.Length) { [void]$sb.Append($prompt.Substring($pos)) }
            $prompt = $sb.ToString()
        }
        if ($reply -and $rxCiteSent.IsMatch($reply))
        {
            $sb = [System.Text.StringBuilder]::new($reply.Length)
            $pos = 0
            foreach ($m in $rxCiteSent.Matches($reply))
            {
                if ($m.Index -gt $pos) { [void]$sb.Append($reply.Substring($pos, $m.Index - $pos)) }
                [void]$sb.Append([string]$inlineCites[[int]$m.Groups[1].Value])
                $pos = $m.Index + $m.Length
            }
            if ($pos -lt $reply.Length) { [void]$sb.Append($reply.Substring($pos)) }
            $reply = $sb.ToString()
        }
    }

    $exchanges.Add([pscustomobject]@{
            Index     = $exchangeIdx
            Prompt    = $prompt
            Reply     = $reply
            Citations = $citations
        })
    $exchangeIdx++
}

if (-not $includeMeta) { return $exchanges.ToArray() }

return [pscustomobject]@{
    Id        = $id
    Path      = $path
    Exchanges = $exchanges.ToArray()
    Processor = 'threadparser-perplexity'
}

using namespace System
using namespace System.Collections.Concurrent
using namespace System.Management.Automation
using namespace System.Management.Automation.Runspaces
using namespace System.Threading

#Requires -Version 7.6
Set-StrictMode -Version Latest

enum IssPreset
{
    Bare  # CreateEmpty       — bare PS engine; processor scripts must be fully self-contained
    Core  # CreateDefault2    — PS core cmdlets only; default; good isolation/speed balance
    Full  # CreateDefault     — full module + provider set; use when processors need providers
}

$script:ReadProcessorScript = {
    param([string]$Key, [string]$Path)
    $result = @{ Key = $Key; Fn = "Invoke-$Key"; Body = $null; Error = $null }
    try
    {
        if ([string]::IsNullOrWhiteSpace($Key)) { $result.Error = 'Processor key cannot be empty.'; return $result }
        if ([string]::IsNullOrWhiteSpace($Path)) { $result.Error = 'Processor path cannot be empty.'; return $result }
        if (-not (Test-Path -LiteralPath $Path)) { $result.Error = "Script not found: $Path"; return $result }

        $body = Get-Content -LiteralPath $Path -Raw

        if ($body -match '(?m)^\s*#\s*Requires\b')
        {
            $result.Error = 'Processor scripts must not declare #Requires (ISS-load contract).'
            return $result
        }
        if ($body -match '(?m)^\s*function\s+[A-Za-z0-9_-]+\b')
        {
            $result.Error = 'Processor scripts must not contain an outer function declaration — body only, param($Item, $Config) contract.'
            return $result
        }

        $result.Body = $body
    }
    catch { $result.Error = $_.Exception.Message }
    return $result
}

function Build-Iss
{
    param(
        [IssPreset] $Preset = [IssPreset]::Core,
        [string[]]  $Modules = @()
    )

    $iss = switch ($Preset)
    {
        ([IssPreset]::Bare) { [InitialSessionState]::CreateEmpty() }
        ([IssPreset]::Core) { [InitialSessionState]::CreateDefault2() }
        ([IssPreset]::Full) { [InitialSessionState]::CreateDefault() }
        default { [InitialSessionState]::CreateDefault2() }
    }

    foreach ($mod in $Modules)
    {
        if (-not [string]::IsNullOrWhiteSpace($mod)) { $iss.ImportPSModule($mod) }
    }

    return $iss
}

function Compile-Plan
{
    param(
        [Parameter(Mandatory)] [hashtable]  $Manifest,
        [Parameter(Mandatory)] [object[]]   $Steps,
        [Parameter(Mandatory)] [string]     $ChainExecutorPath,
        [IssPreset]                         $IssPreset = [IssPreset]::Core,
        [string[]]                          $IssModules = @(),
        [int]                               $InitThreads = 4
    )

    $errors = [System.Collections.Generic.List[string]]::new()
    $warnings = [System.Collections.Generic.List[string]]::new()

    if ($null -eq $Manifest -or $Manifest.Count -eq 0)
    {
        $errors.Add('Manifest is empty — no processors to load.')
        return [pscustomobject]@{ Plan = $null; Errors = $errors.ToArray(); Warnings = $warnings.ToArray() }
    }
    if ($null -eq $Steps -or $Steps.Count -eq 0)
    {
        $errors.Add('Steps array is empty — nothing to execute.')
        return [pscustomobject]@{ Plan = $null; Errors = $errors.ToArray(); Warnings = $warnings.ToArray() }
    }
    if (-not (Test-Path -LiteralPath $ChainExecutorPath))
    {
        $errors.Add("chain-executor script not found: $ChainExecutorPath")
        return [pscustomobject]@{ Plan = $null; Errors = $errors.ToArray(); Warnings = $warnings.ToArray() }
    }

    $referencedKeys = [System.Collections.Generic.HashSet[string]]::new()
    foreach ($step in $Steps)
    {
        if ([string]::IsNullOrWhiteSpace($step.Key))
        {
            $errors.Add('A step has an empty or missing Key.')
            continue
        }
        [void]$referencedKeys.Add($step.Key)
    }

    foreach ($key in $referencedKeys)
    {
        if (-not $Manifest.ContainsKey($key))
        {
            $errors.Add("Step references processor key '$key' which is absent from the manifest.")
        }
    }

    if ($errors.Count -gt 0)
    {
        return [pscustomobject]@{ Plan = $null; Errors = $errors.ToArray(); Warnings = $warnings.ToArray() }
    }

    $entriesToRead = @($Manifest.GetEnumerator() | Where-Object { $referencedKeys.Contains($_.Key) })

    $batches = [System.Collections.Generic.List[object[]]]::new()
    for ($i = 0; $i -lt $entriesToRead.Count; $i += $InitThreads)
    {
        $end = [Math]::Min($i + $InitThreads, $entriesToRead.Count) - 1
        $batches.Add($entriesToRead[$i..$end])
    }

    $loadedBodies = [System.Collections.Generic.List[hashtable]]::new($entriesToRead.Count)
    $readScript = $script:ReadProcessorScript

    foreach ($batch in $batches)
    {
        $wave = [System.Collections.Generic.List[hashtable]]::new($batch.Count)
        foreach ($entry in $batch)
        {
            $ps = [PowerShell]::Create()
            $null = $ps.AddScript($readScript).AddArgument([string]$entry.Key).AddArgument([string]$entry.Value)
            $async = $ps.BeginInvoke()
            $wave.Add(@{ PS = $ps; Async = $async })
        }
        foreach ($reader in $wave)
        {
            try
            {
                $res = $reader.PS.EndInvoke($reader.Async)
                if ($res -and $res.Count -gt 0) { $loadedBodies.Add($res[0]) }
            }
            catch { $warnings.Add("Bootstrap reader threw: $($_.Exception.Message)") }
            finally { $reader.PS.Dispose() }
        }
    }

    $validBodies = @{}
    foreach ($loaded in $loadedBodies)
    {
        if ($loaded.Error) { $errors.Add("Processor '$($loaded.Key)': $($loaded.Error)"); continue }
        $validBodies[$loaded.Key] = $loaded
    }

    if ($errors.Count -gt 0)
    {
        return [pscustomobject]@{ Plan = $null; Errors = $errors.ToArray(); Warnings = $warnings.ToArray() }
    }

    $iss = Build-Iss -Preset $IssPreset -Modules $IssModules

    foreach ($key in $referencedKeys)
    {
        $entry = $validBodies[$key]
        $iss.Commands.Add(
            [System.Management.Automation.Runspaces.SessionStateFunctionEntry]::new($entry.Fn, $entry.Body)
        )
    }

    $chainBody = Get-Content -LiteralPath $ChainExecutorPath -Raw
    $iss.Commands.Add(
        [System.Management.Automation.Runspaces.SessionStateFunctionEntry]::new('Invoke-ChainExecutor', $chainBody)
    )

    $boundSteps = foreach ($step in $Steps)
    {
        [pscustomobject]@{
            Key    = [string]$step.Key
            Fn     = [string]$validBodies[$step.Key].Fn
            Config = $step.Config ?? @{}
        }
    }

    return [pscustomobject]@{
        Plan     = [pscustomobject]@{
            Steps         = @($boundSteps)
            Iss           = $iss
            ProcessorKeys = @($referencedKeys)
        }
        Errors   = @()
        Warnings = $warnings.ToArray()
    }
}

function Resolve-WorkerBudget
{
    param(
        [Parameter(Mandatory)] [int]           $ItemCount,
        [nullable[int]]                        $MaxWorkers = $null,
        [int]                                  $ReservedCores = 2,
        [int]                                  $MinItemsPerWorker = 4
    )

    $warnings = [System.Collections.Generic.List[string]]::new()
    $logical = [Math]::Max(1, [Environment]::ProcessorCount)

    if ($null -ne $MaxWorkers)
    {
        $policy = 'Explicit'
        if ($MaxWorkers -gt $logical)
        {
            $warnings.Add("MaxWorkers ($MaxWorkers) exceeds logical core count ($logical); clamping.")
            $MaxWorkers = $logical
        }
        $ceiling = [Math]::Max(1, $MaxWorkers)
    }
    else
    {
        $policy = 'Auto'
        $reserved = [Math]::Min($ReservedCores, $logical - 1)   # always leave at least 1 core
        $ceiling = [Math]::Max(1, $logical - $reserved)
    }

    $graded = if ($MinItemsPerWorker -gt 0 -and $ItemCount -gt 0)
    {
        [Math]::Max(1, [int][Math]::Ceiling($ItemCount / $MinItemsPerWorker))
    }
    else { $ceiling }

    $threads = [Math]::Min($ceiling, $graded)
    $threads = [Math]::Max(1, [Math]::Min($threads, [Math]::Max(1, $ItemCount)))

    return [pscustomobject]@{
        Threads  = $threads
        Policy   = $policy
        Warnings = $warnings.ToArray()
        Inputs   = [pscustomobject]@{
            ItemCount         = $ItemCount
            MaxWorkers        = $MaxWorkers
            ReservedCores     = $ReservedCores
            MinItemsPerWorker = $MinItemsPerWorker
            LogicalCores      = $logical
        }
    }
}

function Invoke-Plan
{
    param(
        [Parameter(Mandatory)] [object[]]       $Items,
        [Parameter(Mandatory)] [pscustomobject] $Plan,
        [nullable[int]]                         $MaxWorkers = $null,
        [int]                                   $ReservedCores = 2,
        [int]                                   $MinItemsPerWorker = 4,
        [int]                                   $WaitTimeoutMs = 60000
    )

    $errors = [System.Collections.Concurrent.ConcurrentBag[string]]::new()
    $warnings = [System.Collections.Generic.List[string]]::new()
    $timing = @{}
    $swTotal = [System.Diagnostics.Stopwatch]::StartNew()

    $budgetParams = @{
        ItemCount         = $Items.Count
        MaxWorkers        = $MaxWorkers
        ReservedCores     = $ReservedCores
        MinItemsPerWorker = $MinItemsPerWorker
    }
    $budget = Resolve-WorkerBudget @budgetParams

    foreach ($w in $budget.Warnings) { $warnings.Add($w) }

    $threads = $budget.Threads
    $count = $Items.Count

    $ordered = [object[]]::new($count)

    if ($count -eq 0)
    {
        return [pscustomobject]@{
            Results  = $ordered
            Errors   = @()
            Warnings = $warnings.ToArray()
            Budget   = $budget
            Timing   = [pscustomobject]@{ TotalMs = 0 }
        }
    }

    $sliceItems = [System.Collections.Generic.List[object][]]::new($threads)
    $sliceIdxs = [System.Collections.Generic.List[int][]]::new($threads)
    for ($t = 0; $t -lt $threads; $t++)
    {
        $sliceItems[$t] = [System.Collections.Generic.List[object]]::new()
        $sliceIdxs[$t] = [System.Collections.Generic.List[int]]::new()
    }
    for ($i = 0; $i -lt $count; $i++)
    {
        $slot = $i % $threads
        $sliceItems[$slot].Add($Items[$i])
        $sliceIdxs[$slot].Add($i)
    }

    $swPool = [System.Diagnostics.Stopwatch]::StartNew()
    $pool = [RunspaceFactory]::CreateRunspacePool($Plan.Iss)
    $null = $pool.SetMinRunspaces(1)
    $null = $pool.SetMaxRunspaces($threads)
    $pool.ThreadOptions = [PSThreadOptions]::UseNewThread
    $pool.ApartmentState = [ApartmentState]::MTA
    $pool.Open()
    $timing['PoolOpenMs'] = $swPool.ElapsedMilliseconds

    $workerScript = {
        param(
            [object[]]  $MyItems,
            [int[]]     $MyIdxs,
            [object[]]  $PlanSteps,    # array of hashtable @{ Key; Fn; Config }
            [object[]]  $OrderedOut,
            [System.Collections.Concurrent.ConcurrentBag[string]] $ErrorBag
        )

        $plan = @{ Steps = $PlanSteps }

        for ($i = 0; $i -lt $MyItems.Length; $i++)
        {
            $ceParams = @{
                Item     = $MyItems[$i]
                Plan     = $plan
                ErrorBag = $ErrorBag
                Index    = $MyIdxs[$i]
            }
            $OrderedOut[$MyIdxs[$i]] = Invoke-ChainExecutor @ceParams
        }
    }

    $planStepsForWorker = @(
        $Plan.Steps | ForEach-Object { @{ Key = $_.Key; Fn = $_.Fn; Config = $_.Config } }
    )

    $workers = [System.Collections.Generic.List[hashtable]]::new($threads)
    $swDispatch = [System.Diagnostics.Stopwatch]::StartNew()

    for ($w = 0; $w -lt $threads; $w++)
    {
        $slice = $sliceItems[$w].ToArray()
        if (-not $slice -or $slice.Length -eq 0) { continue }
        $idxs = $sliceIdxs[$w].ToArray()

        $ps = [PowerShell]::Create()
        $cmd = $ps.AddScript($workerScript)
        [void]$cmd.AddArgument($slice).AddArgument($idxs).AddArgument($planStepsForWorker).AddArgument($ordered).AddArgument($errors)

        $ps.RunspacePool = $pool
        $async = $ps.BeginInvoke()
        $workers.Add(@{ PS = $ps; Async = $async })
    }
    $timing['DispatchMs'] = $swDispatch.ElapsedMilliseconds

    $swWait = [System.Diagnostics.Stopwatch]::StartNew()
    $swWall = [System.Diagnostics.Stopwatch]::StartNew()
    foreach ($worker in $workers)
    {
        $remaining = [Math]::Max(50, $WaitTimeoutMs - [int]$swWall.ElapsedMilliseconds)
        if (-not $worker.Async.AsyncWaitHandle.WaitOne($remaining))
        {
            $errors.Add('Worker timed out waiting for completion.')
        }
    }
    $timing['WaitMs'] = $swWait.ElapsedMilliseconds

    $swCollect = [System.Diagnostics.Stopwatch]::StartNew()
    foreach ($worker in $workers)
    {
        try
        {
            if ($worker.Async.IsCompleted)
            {
                $null = $worker.PS.EndInvoke($worker.Async)
                if ($worker.PS.HadErrors)
                {
                    $msgs = @($worker.PS.Streams.Error | ForEach-Object { $_.ToString() }) -join '; '
                    $errors.Add("Worker stream errors: $msgs")
                }
            }
            else
            {
                try { $worker.PS.Stop() } catch {}
                $errors.Add('Worker did not complete before timeout; stopped forcibly.')
            }
        }
        catch { $errors.Add("Worker collect error: $($_.Exception.Message)") }
        finally { $worker.PS.Dispose() }
    }
    $timing['CollectMs'] = $swCollect.ElapsedMilliseconds

    try { $pool.Close(); $pool.Dispose() } catch {}

    $timing['TotalMs'] = $swTotal.ElapsedMilliseconds

    return [pscustomobject]@{
        Results  = $ordered
        Errors   = @($errors.ToArray())
        Warnings = $warnings.ToArray()
        Budget   = $budget
        Timing   = [pscustomobject]$timing
    }
}

class RunspaceManager
{
    [pscustomobject] $Plan
    [nullable[int]]  $MaxWorkers = $null
    [int]            $ReservedCores = 2
    [int]            $MinItemsPerWorker = 4
    [int]            $WaitTimeoutMs = 60000

    RunspaceManager([pscustomobject]$plan)
    {
        if ($null -eq $plan) { throw 'Plan cannot be null — call Compile-Plan first and check Errors.' }
        $this.Plan = $plan
    }

    [pscustomobject] Run([object[]]$items)
    {
        $ipParams = @{
            Items             = $items
            Plan              = $this.Plan
            MaxWorkers        = $this.MaxWorkers
            ReservedCores     = $this.ReservedCores
            MinItemsPerWorker = $this.MinItemsPerWorker
            WaitTimeoutMs     = $this.WaitTimeoutMs
        }
        return Invoke-Plan @ipParams
    }
}

function New-RunspaceManager
{
    [OutputType([RunspaceManager])]
    param(
        [Parameter(Mandatory)] [pscustomobject] $Plan,
        [nullable[int]]                         $MaxWorkers = $null,
        [int]                                   $ReservedCores = 2,
        [int]                                   $MinItemsPerWorker = 4,
        [int]                                   $WaitTimeoutMs = 60000
    )

    $mgr = [RunspaceManager]::new($Plan)
    $mgr.MaxWorkers = $MaxWorkers
    $mgr.ReservedCores = $ReservedCores
    $mgr.MinItemsPerWorker = $MinItemsPerWorker
    $mgr.WaitTimeoutMs = $WaitTimeoutMs
    return $mgr
}

